function floorRoot(x: number): number {
  let lo = 0, hi = x;
  while (lo < hi) {
    const mid = Math.floor((lo + hi + 1) / 2); // upper middle, so lo = mid always moves
    if (mid * mid <= x) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

